import pandas as pd

def find_polarized_books(books: pd.DataFrame, reviews: pd.DataFrame) -> pd.DataFrame:
    if books.empty or reviews.empty:
        return pd.DataFrame(columns=['book_id', 'title', 'author', 'genre', 'total_reviews', 'positive_pct', 'negative_pct'])

    merged = pd.merge(books, reviews, on='book_id')

    def calc_stats(group):
        total = len(group)
        pos = (group['rating'] >= 4).sum()
        neg = (group['rating'] <= 2).sum()
        return pd.Series({
            'total_reviews': total,
            'positive_pct': round((pos * 100.0) / total, 2),
            'negative_pct': round((neg * 100.0) / total, 2)
        })

    stats = merged.groupby(['book_id', 'title', 'author', 'genre']).apply(calc_stats, include_groups=False).reset_index()
    res = stats[(stats['total_reviews'] >= 5) & (stats['positive_pct'] >= 30.0) & (stats['negative_pct'] >= 30.0)]
    return res.sort_values(by='book_id', ascending=True)
